import React from 'react';

const WhatIsSection = () => {
  const s = {
    section: { background: '#fff', padding: '90px 32px', fontFamily: 'Poppins, sans-serif' },
    wrapper: { maxWidth: 1200, margin: '0 auto' },
    title: {
      fontSize: 34, fontWeight: 800, color: '#111',
      fontFamily: 'Poppins, sans-serif', letterSpacing: '-0.6px',
      marginBottom: 40, lineHeight: 1.2,
    },
    orange: { color: '#FF5A00' },
    btns: { display: 'flex', gap: 14, flexWrap: 'wrap', marginBottom: 40 },
    btnOrange: {
      background: '#FF5A00', color: '#fff',
      padding: '14px 32px', borderRadius: 12,
      fontSize: 15, fontWeight: 600, fontFamily: 'Poppins, sans-serif',
      border: 'none', cursor: 'pointer',
      boxShadow: '0 6px 22px rgba(255,90,0,.3)',
      transition: 'all .2s',
    },
    imgWrap: {
      width: '100%', borderRadius: 18, overflow: 'hidden',
      height: 540, // Hauteur augmentée de 440 à 540
      position: 'relative', // Ajouté pour pouvoir positionner l'overlay Play au centre
    },
    img: {
      width: '100%', height: '100%',
      objectFit: 'cover', objectPosition: 'center 20%',
      display: 'block',
    },
    // Styles pour l'overlay et le bouton Play centré
    videoOverlay: {
      position: 'absolute',
      inset: 0,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'rgba(0, 0, 0, 0.05)', // Un voile très léger pour détacher le bouton blanc
    },
    centerPlayBtn: {
      width: 76,
      height: 76,
      borderRadius: '50%',
      background: 'rgba(255, 255, 255, 0.85)', // Cercle blanc léger
      backdropFilter: 'blur(4px)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      border: 'none',
      cursor: 'pointer',
      boxShadow: '0 8px 24px rgba(0,0,0,0.12)',
      transition: 'transform 0.2s ease',
    }
  };

  return (
    <section style={s.section}>
      <div style={s.wrapper}>
        <h2 style={s.title}>
          <span style={s.orange}>Djamano</span>, c'est quoi ?
        </h2>

        {/* Le bouton "Suivre la vidéo" a été supprimé ici */}
        <div style={s.btns}>
          <button style={s.btnOrange}>Créer un évènement</button>
        </div>

        {/* Encart vidéo avec la hauteur modifiée et le bouton Play au milieu */}
        <div style={s.imgWrap}>
          <img
            src="/ig.jpg"
            alt="Djamano - collaboration et événementiel"
            style={s.img}
          />

          {/* Calque centré contenant le bouton Play */}
          <div style={s.videoOverlay}>
            <button style={s.centerPlayBtn} title="Lancer la vidéo">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="#FF5A00" style={{ marginLeft: 4 }}>
                <path d="M8 5v14l11-7z"/>
              </svg>
            </button>
          </div>
        </div>
      </div>
    </section>
  );
};

export default WhatIsSection;
